import java.io.*; import java.math.*; import java.security.*; import java.text.*; import java.util.*; import java.util.concurrent.*; import java.util.regex.*; class Result { public static String angryProfessor(int k, List<Integer> a) { int count = 0; for (int time : a) { if (time <= 0) { count++; } } if (count < k) { return "YES"; } else { return "NO"; } } } public class Solution { public static void main(String[] args) throws IOException { BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in)); BufferedWriter bufferedWriter = new BufferedWriter(new OutputStreamWriter(System.out)); String tStr = bufferedReader.readLine(); if (tStr == null) return; int t = Integer.parseInt(tStr.trim()); for (int tItr = 0; tItr < t; tItr++) { String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" "); int n = Integer.parseInt(firstMultipleInput[0]); int k = Integer.parseInt(firstMultipleInput[1]); String[] aTemp = bufferedReader.readLine().replaceAll("\\s+$", "").split(" "); List<Integer> a = new ArrayList<Integer>(); for (int i = 0; i < n; i++) { int aItem = Integer.parseInt(aTemp[i]); a.add(aItem); } String result = Result.angryProfessor(k, a); bufferedWriter.write(result); bufferedWriter.newLine(); } bufferedReader.close(); bufferedWriter.close(); } }